    "sourceSubject": "中医内科学",
    "number": 44,
    "sourceQuestionNumber": 1,
    "sourceSectionNumber": null,
    "type": "B1",
    "stem": "心悸阴虚证可伴有的病理因素有",
    "options": {
      "A": "瘀血、寒凝",
      "B": "气血瘀滞",
      "C": "寒凝，气滞",
      "D": "火盛、痰热",
      "E": "水饮、痰湿"
    },
    "answer": "D",
    "explanation": "心悸阴虚证，阴虚火旺，可伴有火盛、痰热等病理因素。心悸阳虚证，心阳不振，水饮不化，可伴有水饮、痰湿等病理因素。",
    "prompt": "心悸阴虚证可伴有的病理因素有",
    "groupId": "subject-f8eb0c1c1d57-B1-G008",
