    "explanation": "中风恢复期的治法包括搜风化痰、行瘀通络、益气养血、滋养肝肾等，搜风化痰是中风恢复期常用治法。针对痫痰难化这一特点而制定的治法为辛热开破，用辛热开破之品（如半夏、天南星、白附子等）以开破痰结。涤痰醒神适用于痫病痰浊蒙窍证；豁痰化瘀适用于痫病瘀阻脑络证；平肝潜阳适用于肝阳上亢证。",
