    "type": "A1/A2",
    "stem": "患者，女，34岁。有痫证病史16年。神思恍惚，面色晦暗头晕目眩，伴两目干涩，耳轮焦枯不泽，健忘失眠，腰膝酸软，大便干燥，舌质红，苔薄白或薄黄少津，脉沉细数。治法当为",
    "options": {
      "A": "滋养肝肾，填精益髓",
      "B": "补益心肾，健脾化痰",
      "C": "健脾补肾，健脑宁神",
      "D": "平肝健脾，补肾宁神",
      "E": "平肝熄风，健脾补肾"
    },
