    "explanation": "患儿脸颊处有数个大小不等的扁平样赘生物，轻度隆起，表面光滑，呈圆形、椭圆形或多角形，边界清楚，诊断为扁瘊（扁平疣）。扁瘊好发于颜面、手背，表现为表面光滑的扁平丘疹，呈圆形、椭圆形或多角形，边界清楚，质硬，正常肤色或淡褐色。",
