    "explanation": "患者大便带血，严重时喷射状出血，血色鲜红，时有肛门瘙痒，舌质红苔薄黄脉浮数，诊断为内痔。内痔的主要症状是便血、脱出，Ⅰ期内痔以便血为主，血色鲜红，可呈喷射状出血，一般无脱出。",
