    "sourceQuestionNumber": 23,
    "sourceSectionNumber": null,
    "type": "A1/A2",
    "stem": "患者月经周期延后，量正常，色暗红，有血块，小腹胀痛，胸胁乳房胀痛；舌质正常，苔薄白，脉弦。治疗应首选的方剂是",
