    "sourceSectionNumber": null,
    "type": "A1/A2",
    "stem": "加减一阴煎主要适用于",
    "options": {
      "A": "肾气亏损证闭经",
      "B": "阴虚血燥证闭经",
      "C": "肝肾亏损证闭经",
      "D": "阴虚血热证闭经",
      "E": "湿热蕴结证闭经"
    },
