    "sharedStem": "患者48岁，月经紊乱，心烦失眠，心悸易惊，甚至情志失常，月经周期紊乱，量少或多，经色鲜红，头晕健忘，腰酸乏力；舌红，苔少，脉细数。",
    "groupStart": 48,
