    "answer": "C",
    "explanation": "益母草、牛膝皆能活血通经、利水。益母草活血调经、利尿消肿、清热解毒；牛膝活血通经、补肝肾、强筋骨、利水通淋、引火（血）下行。二者均能活血通经、利水。",
